import React, { createContext, useContext, useEffect, useState } from 'react'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/**
 * 主题类型
 */
export type ThemeMode = 'light' | 'dark' | 'system'

/**
 * 主题上下文值
 */
interface ThemeContextValue {
  /** 当前主题模式 */
  mode: ThemeMode
  /** 实际应用的主题（解析 system 后） */
  resolvedMode: 'light' | 'dark'
  /** 设置主题模式 */
  setMode: (mode: ThemeMode) => void
  /** 切换主题 */
  toggleTheme: () => void
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined)

/**
 * 获取系统主题偏好
 */
function getSystemThemePreference(): 'light' | 'dark' {
  if (typeof window === 'undefined') {
    return 'light'
  }
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

/**
 * 从 localStorage 读取保存的主题
 */
function getStoredTheme(): ThemeMode | null {
  if (typeof window === 'undefined') {
    return null
  }
  const stored = localStorage.getItem('v9-theme')
  if (stored === 'light' || stored === 'dark' || stored === 'system') {
    return stored
  }
  return null
}

/**
 * 保存主题到 localStorage
 */
function storeTheme(mode: ThemeMode): void {
  if (typeof window === 'undefined') {
    return
  }
  localStorage.setItem('v9-theme', mode)
}

/**
 * 应用主题到 DOM
 */
function applyTheme(resolvedMode: 'light' | 'dark'): void {
  if (typeof document === 'undefined') {
    return
  }
  const root = document.documentElement
  root.setAttribute('data-theme', resolvedMode)

  // 同时设置 class 以兼容 Tailwind darkMode: 'class'
  if (resolvedMode === 'dark') {
    root.classList.add('dark')
  } else {
    root.classList.remove('dark')
  }

  logger.info('[ThemeProvider] 主题已应用', { theme: resolvedMode })
}

/**
 * ThemeProvider 属性
 */
interface ThemeProviderProps {
  children: React.ReactNode
  /** 默认主题模式 */
  defaultMode?: ThemeMode
}

/**
 * 主题提供者组件
 * 
 * @description
 * 提供主题上下文，管理 light/dark/system 主题切换。
 * 主题偏好保存在 localStorage 中，支持系统主题检测。
 * 
 * @example
 * ```tsx
 * <ThemeProvider defaultMode="system">
 *   <App />
 * </ThemeProvider>
 * ```
 */
export function ThemeProvider({ children, defaultMode = 'system' }: ThemeProviderProps): React.JSX.Element {
  // 初始化主题状态
  const [mode, setModeState] = useState<ThemeMode>(() => {
    return getStoredTheme() ?? defaultMode
  })

  // 解析实际主题模式
  const resolvedMode = mode === 'system' ? getSystemThemePreference() : mode

  // 应用主题到 DOM
  useEffect(() => {
    applyTheme(resolvedMode)
    storeTheme(mode)
  }, [mode, resolvedMode])

  // 监听系统主题变化
  useEffect(() => {
    if (mode !== 'system') {
      return
    }

    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)')
    const handleChange = (): void => {
      const newSystemTheme = mediaQuery.matches ? 'dark' : 'light'
      applyTheme(newSystemTheme)
      logger.info('[ThemeProvider] 系统主题变化', { theme: newSystemTheme })
    }

    mediaQuery.addEventListener('change', handleChange)
    return () => mediaQuery.removeEventListener('change', handleChange)
  }, [mode])

  // 设置主题模式
  const setMode = (newMode: ThemeMode): void => {
    logger.info('[ThemeProvider] 设置主题模式', { mode: newMode })
    setModeState(newMode)
  }

  // 切换主题（light <-> dark）
  const toggleTheme = (): void => {
    const newMode = resolvedMode === 'light' ? 'dark' : 'light'
    logger.info('[ThemeProvider] 切换主题', { from: resolvedMode, to: newMode })
    setModeState(newMode)
  }

  const contextValue: ThemeContextValue = {
    mode,
    resolvedMode,
    setMode,
    toggleTheme,
  }

  return (
    <ThemeContext.Provider value={contextValue}>
      {children}
    </ThemeContext.Provider>
  )
}

/**
 * 使用主题上下文 Hook
 * 
 * @throws Error 如果在 ThemeProvider 外部使用
 * 
 * @example
 * ```tsx
 * function ThemeToggle() {
 *   const { mode, resolvedMode, toggleTheme } = useTheme()
 *   return (
 *     <button onClick={toggleTheme}>
 *       当前主题: {resolvedMode}
 *     </button>
 *   )
 * }
 * ```
 */
export function useTheme(): ThemeContextValue {
  const context = useContext(ThemeContext)
  if (context === undefined) {
    throw new Error('useTheme 必须在 ThemeProvider 内部使用')
  }
  return context
}

/**
 * 主题切换按钮组件（可选）
 */
interface ThemeToggleProps {
  /** 自定义渲染函数 */
  children?: (context: ThemeContextValue) => React.ReactNode
}

export function ThemeToggle({ children }: ThemeToggleProps): React.JSX.Element {
  const themeContext = useTheme()

  if (children) {
    return <>{children(themeContext)}</>
  }

  return (
    <button
      type="button"
      onClick={themeContext.toggleTheme}
      className="inline-flex items-center justify-center rounded-md p-2 hover:bg-gray-100 dark:hover:bg-gray-800"
      aria-label={`切换到${themeContext.resolvedMode === 'light' ? '暗色' : '亮色'}模式`}
    >
      {themeContext.resolvedMode === 'light' ? (
        <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
        </svg>
      ) : (
        <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
        </svg>
      )}
    </button>
  )
}

import { getLogger } from '@/lib/logger'
import {
  ACL_MATRIX,
  DB_OPERATION,
  type DbOperation,
  type ModuleId,
  type StoreName,
} from '@/config/dbConfig'

const logger = getLogger()

export class AclError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'AclError'
  }
}

interface AclCheckInput {
  module: ModuleId
  store: StoreName
  operation: DbOperation
}

export function inferOperation(action: string): DbOperation {
  if (action.includes('INSERT') || action.includes('SAVE') || action.includes('INGEST')) {
    logger.debug(`[ACL] inferOperation: action="${action}" → "${DB_OPERATION.insert}"`)
    return DB_OPERATION.insert
  }
  if (action.includes('UPDATE')) {
    logger.debug(`[ACL] inferOperation: action="${action}" → "${DB_OPERATION.update}"`)
    return DB_OPERATION.update
  }
  if (action.includes('DELETE') || action.includes('CLEAR')) {
    logger.debug(`[ACL] inferOperation: action="${action}" → "${DB_OPERATION.delete}"`)
    return DB_OPERATION.delete
  }
  logger.debug(`[ACL] inferOperation: action="${action}" → "${DB_OPERATION.select}"`)
  return DB_OPERATION.select
}

export class AclEngine {
  assert({ module, store, operation }: AclCheckInput): void {
    logger.debug(`[ACL] assert() called: module="${module}", store="${store}", operation="${operation}"`)

    const permission = ACL_MATRIX[module]

    if (!permission) {
      logger.error(`[ACL] Permission denied: Module "${module}" is not registered in ACL`)
      throw new AclError(`Module ${module} is not registered in ACL`)
    }

    logger.debug(`[ACL] Found permissions for module "${module}": actions=${JSON.stringify(permission.actions)}`)

    if (!permission.actions.includes(operation)) {
      logger.error(`[ACL] Permission denied: Module "${module}" is not allowed to perform "${operation}"`)
      throw new AclError(
        `Module ${module} is not allowed to perform ${operation}`,
      )
    }

    const allowedStores =
      operation === DB_OPERATION.select ? permission.read : permission.write

    logger.debug(`[ACL] Checking store access: operation="${operation}", allowedStores=${JSON.stringify(allowedStores)}`)

    if (!allowedStores.includes(store)) {
      logger.error(`[ACL] Permission denied: Module "${module}" cannot "${operation}" on store "${store}"`)
      throw new AclError(
        `Module ${module} cannot ${operation} on store ${store}`,
      )
    }

    logger.info(`[ACL] Permission granted: module="${module}", store="${store}", operation="${operation}"`)
  }
}

export const aclEngine = new AclEngine()

import { ENVELOPE_ACTION, STORE_NAME, type EnvelopeTarget, type ModuleId, type StoreName } from '@/config/dbConfig'
import { db } from '@/data/db'
import type { Stock } from '@/data/types'
import { CHANGED_SUFFIX, EVENT_NAMES } from '@/constants/store-channels.constants'
import { eventBus } from '@/lib/eventBus'
import { getLogger } from '@/lib/logger'
import { analyze as analyzeHotSector, type HotSectorAnalyzerInput } from '@/services/scoring/hotSectorAnalyzer'
import { detect as detectRotation, type RotationSignalInput } from '@/services/scoring/rotationSignalDetector'
import { analyze as analyzeValuePit, type ValuePitAnalyzerInput } from '@/services/scoring/valuePitAnalyzer'
import { aclEngine, inferOperation } from './acl'
import { EnvelopeError, EnvelopeFactory, type StandardEnvelope } from './envelope'
import { fallbackQueue, FallbackQueue } from './fallbackQueue'
import { MemoryCache } from './memoryCache'

/**
 * 信封处理器接口（策略模式）
 * 每个 action 对应一个 Handler，负责具体的数据库操作
 */
interface EnvelopeHandler {
  canHandle(action: string): boolean
  handle(envelope: StandardEnvelope, store: StoreName): Promise<void>
}

/**
 * 通用 PUT 操作处理器
 * 处理所有简单的 db.put() 操作
 */
class PutHandler implements EnvelopeHandler {
  private readonly actions: string[]

  constructor(actions: string[]) {
    this.actions = actions
  }

  canHandle(action: string): boolean {
    return this.actions.includes(action)
  }

  async handle(envelope: StandardEnvelope, store: StoreName): Promise<void> {
    const { meta, payload } = envelope
    logger.debug(`[DataBridge] DB put: action="${meta.action}", store="${store}"`)
    await db.put(store, payload)
  }
}

/**
 * 通用 DELETE 操作处理器
 */
class DeleteHandler implements EnvelopeHandler {
  private readonly actions: string[]

  constructor(actions: string[]) {
    this.actions = actions
  }

  canHandle(action: string): boolean {
    return this.actions.includes(action)
  }

  async handle(envelope: StandardEnvelope, store: StoreName): Promise<void> {
    const { meta, payload } = envelope
    const { id } = payload as { id: string }
    logger.debug(`[DataBridge] DB delete: action="${meta.action}", store="${store}", id="${id}"`)
    await db.delete(store, id)
  }
}

/**
 * 股票插入处理器（需要特殊处理）
 */
class InsertStockHandler implements EnvelopeHandler {
  canHandle(action: string): boolean {
    return action === ENVELOPE_ACTION.insertStock
  }

  async handle(envelope: StandardEnvelope, store: StoreName): Promise<void> {
    const stock = envelope.payload as Stock
    // 防御性校验：stocks store 的 keyPath 为 'symbol'，缺失会导致 IndexedDB 抛出
    // "Evaluating the object store's key path did not yield a value"
    if (!stock || !stock.symbol) {
      const traceId = envelope.meta.traceId ?? 'N/A'
      throw new EnvelopeError(
        `insertStock rejected: missing or empty "symbol" field (traceId=${traceId})`,
      )
    }
    logger.debug(`[DataBridge] DB insertStock: symbol="${stock.symbol}"`)
    await db.put(store, stock)
  }
}

/**
 * 股票更新处理器（需要合并现有数据）
 */
class UpdateStockHandler implements EnvelopeHandler {
  canHandle(action: string): boolean {
    return action === ENVELOPE_ACTION.updateStock
  }

  async handle(envelope: StandardEnvelope, store: StoreName): Promise<void> {
    const update = envelope.payload as Partial<Stock> & { symbol: string }
    logger.debug(`[DataBridge] DB updateStock: symbol="${update.symbol}"`)
    const existing = await db.get<Stock>(store, update.symbol)
    if (!existing) {
      logger.warn(`[DataBridge] DB updateStock failed: Stock not found "${update.symbol}"`)
      throw new EnvelopeError(`Stock not found: ${update.symbol}`)
    }
    await db.put(store, { ...existing, ...update, updatedAt: Date.now(), dataVersion: (existing.dataVersion ?? 1) + 1 })
  }
}

/**
 * 股票删除处理器（需要级联删除）
 */
class DeleteStockHandler implements EnvelopeHandler {
  canHandle(action: string): boolean {
    return action === ENVELOPE_ACTION.deleteStock
  }

  async handle(envelope: StandardEnvelope, store: StoreName): Promise<void> {
    const { symbol } = envelope.payload as { symbol: string }
    logger.info(`[DataBridge] DB deleteStock: symbol="${symbol}" — 开始级联删除`)

    // 1. 删除 Stock 主记录
    await db.delete(store, symbol)

    // 2. 级联删除以 symbol 为主键的关联表
    const symbolKeyStores = [
      STORE_NAME.v6Scores,
      STORE_NAME.dailyQuotes,
      STORE_NAME.hotSectorScores,
      STORE_NAME.valuePitScores,
    ]
    for (const s of symbolKeyStores) {
      try {
        await db.delete(s, symbol)
        logger.debug(`[DataBridge] 级联删除: ${s} symbol="${symbol}"`)
      } catch (err) {
        logger.warn(`[DataBridge] 级联删除失败(主键): ${s}`, { error: err instanceof Error ? err.message : String(err) })
      }
    }

    // 3. 级联删除有 by-symbol 索引的关联表（先查后删）
    const indexedStores = [
      STORE_NAME.intelligentScores,
      STORE_NAME.scoreDocs,
      STORE_NAME.localDocs,
      STORE_NAME.newsStockMap,
      STORE_NAME.executionPlans,
      STORE_NAME.executionLogs,
      STORE_NAME.missingReports,
    ]
    for (const s of indexedStores) {
      try {
        const records = await db.getAllByIndex<{ id: string; symbol?: string }>(s, 'by-symbol', symbol)
        for (const rec of records) {
          if (rec.id) {
            await db.delete(s, rec.id)
          }
        }
        if (records.length > 0) {
          logger.debug(`[DataBridge] 级联删除(索引): ${s} count=${records.length}`)
        }
      } catch (err) {
        logger.warn(`[DataBridge] 级联删除失败(索引): ${s}`, { error: err instanceof Error ? err.message : String(err) })
      }
    }

    // 4. 级联删除无 symbol 索引的关联表（全表扫描过滤）
    const scanStores = [STORE_NAME.orders, STORE_NAME.signals, STORE_NAME.watchlists]
    for (const s of scanStores) {
      try {
        const allRecords = await db.getAll<{ id: string; symbol?: string }>(s)
        const toDelete = allRecords.filter((r) => r.symbol === symbol)
        for (const rec of toDelete) {
          if (rec.id) {
            await db.delete(s, rec.id)
          }
        }
        if (toDelete.length > 0) {
          logger.debug(`[DataBridge] 级联删除(扫描): ${s} count=${toDelete.length}`)
        }
      } catch (err) {
        logger.warn(`[DataBridge] 级联删除失败(扫描): ${s}`, { error: err instanceof Error ? err.message : String(err) })
      }
    }

    logger.info(`[DataBridge] DB deleteStock 完成: symbol="${symbol}" — 级联删除结束`)
  }
}

/**
 * 通知类 action 处理器（仅记录日志，不持久化）
 */
class NotificationHandler implements EnvelopeHandler {
  private readonly actions: string[]

  constructor(actions: string[]) {
    this.actions = actions
  }

  canHandle(action: string): boolean {
    return this.actions.includes(action)
  }

  async handle(envelope: StandardEnvelope): Promise<void> {
    const { meta } = envelope
    logger.info(`[DataBridge] Notification-only action, skip DB put: action="${meta.action}"`)
  }
}

/**
 * 持仓数据查询处理器（P0-3 修复）
 * loadHoldingsData 的 payload 是 HoldingsQueryParams（分页/日期/关键词），
 * 不是 Stock 数据，不能写入 stocks store（keyPath='symbol'）。
 * holdingsStore 的 ACL write=[] 也证实它不应执行 DB 写操作。
 * 此处理器仅记录查询日志，不执行 DB 写入。
 */
class LoadHoldingsDataHandler implements EnvelopeHandler {
  canHandle(action: string): boolean {
    return action === ENVELOPE_ACTION.loadHoldingsData
  }

  async handle(envelope: StandardEnvelope): Promise<void> {
    const { meta, payload } = envelope
    logger.info('[DataBridge] loadHoldingsData: query-only action, skip DB put', {
      traceId: meta.traceId,
      source: meta.source,
      payloadKeys: payload ? Object.keys(payload as Record<string, unknown>) : [],
    })
  }
}

/**
 * 信封处理器注册表
 * 按优先级顺序管理所有 Handler
 */
class HandlerRegistry {
  private handlers: EnvelopeHandler[] = []

  register(handler: EnvelopeHandler): void {
    this.handlers.push(handler)
  }

  findHandler(action: string): EnvelopeHandler | undefined {
    return this.handlers.find((h) => h.canHandle(action))
  }
}

/**
 * 初始化处理器注册表
 */
function createHandlerRegistry(): HandlerRegistry {
  const registry = new HandlerRegistry()

  // 1. 特殊处理器（优先级高）
  registry.register(new InsertStockHandler())
  registry.register(new UpdateStockHandler())
  registry.register(new DeleteStockHandler())

  // 2. 通知类处理器
  registry.register(
    new NotificationHandler([
      ENVELOPE_ACTION.newsArticleLoaded,
      ENVELOPE_ACTION.holdingsDataLoaded,
      ENVELOPE_ACTION.tradeActionExecuted,
    ])
  )

  // 2.5 持仓查询处理器（P0-3 修复：loadHoldingsData 的 payload 是 HoldingsQueryParams，
  // 不是 Stock 数据，不应写入 stocks store。holdingsStore 的 ACL write=[] 也证实了这一点）
  registry.register(new LoadHoldingsDataHandler())

  // 3. DELETE 操作处理器
  registry.register(new DeleteHandler([ENVELOPE_ACTION.deleteExecutionPlan]))

  // 4. 通用 PUT 操作处理器（处理所有简单的 db.put() 操作）
  registry.register(
    new PutHandler([
      ENVELOPE_ACTION.saveScores,
      ENVELOPE_ACTION.saveDailyQuotes,
      ENVELOPE_ACTION.saveIntelligentScores,
      ENVELOPE_ACTION.saveIndustryScores,
      ENVELOPE_ACTION.saveRotationScores,
      ENVELOPE_ACTION.saveSectorScores,
      ENVELOPE_ACTION.saveScoreDocs,
      ENVELOPE_ACTION.saveStrategySnapshots,
      ENVELOPE_ACTION.saveHotSectorScores,
      ENVELOPE_ACTION.saveValuePitScores,
      ENVELOPE_ACTION.saveLocalDocs,
      ENVELOPE_ACTION.saveNews,
      ENVELOPE_ACTION.saveNewsStockMap,
      ENVELOPE_ACTION.saveSentimentCache,
      ENVELOPE_ACTION.saveResearchLog,
      ENVELOPE_ACTION.insertOrder,
      ENVELOPE_ACTION.updateOrder,
      ENVELOPE_ACTION.insertSignal,
      ENVELOPE_ACTION.saveTradeReview,
      ENVELOPE_ACTION.updateExecutionPlan,
      ENVELOPE_ACTION.incrementMissingReportRetry,
      ENVELOPE_ACTION.saveExecutionPlan,
      ENVELOPE_ACTION.saveExecutionLog,
      ENVELOPE_ACTION.saveMissingReport,
      ENVELOPE_ACTION.updateExecutionPhase,
      ENVELOPE_ACTION.savePortfolio,
      ENVELOPE_ACTION.newsArticleBookmarked,
    ])
  )

  return registry
}

const logger = getLogger()

type EnvelopeCallback = (envelope: StandardEnvelope) => void

/**
 * forward() 慢调用阈值（毫秒）。超过则记录 warn 日志。
 */
const FORWARD_SLOW_THRESHOLD_MS = 50

/**
 * broadcast() 慢调用阈值（毫秒）。超过则记录 warn 日志。
 */
const BROADCAST_SLOW_THRESHOLD_MS = 10

/**
 * 策略数据流订阅频道名称常量。
 * 外部组件通过 `dataBridge.subscribe(STRATEGY_CHANNEL.hotSector, cb)` 订阅。
 */
export const STRATEGY_CHANNEL = {
  hotSector: 'strategy:hotSector',
  valuePit: 'strategy:valuePit',
  rotationSignal: 'strategy:rotationSignal',
} as const

export type StrategyChannel = (typeof STRATEGY_CHANNEL)[keyof typeof STRATEGY_CHANNEL]

/**
 * Action 到 Store 的显式映射表（避免字符串包含判断的歧义）
 */
const ACTION_TO_STORE_MAP: Record<string, StoreName> = {
  [ENVELOPE_ACTION.saveNewsStockMap]: STORE_NAME.newsStockMap,
  [ENVELOPE_ACTION.insertStock]: STORE_NAME.stocks,
  [ENVELOPE_ACTION.updateStock]: STORE_NAME.stocks,
  [ENVELOPE_ACTION.deleteStock]: STORE_NAME.stocks,
  [ENVELOPE_ACTION.saveDailyQuotes]: STORE_NAME.dailyQuotes,
  [ENVELOPE_ACTION.saveIndustryScores]: STORE_NAME.industryScores,
  [ENVELOPE_ACTION.saveIntelligentScores]: STORE_NAME.intelligentScores,
  [ENVELOPE_ACTION.saveRotationScores]: STORE_NAME.rotationScores,
  [ENVELOPE_ACTION.saveHotSectorScores]: STORE_NAME.hotSectorScores,
  [ENVELOPE_ACTION.saveValuePitScores]: STORE_NAME.valuePitScores,
  [ENVELOPE_ACTION.saveSectorScores]: STORE_NAME.sectorScores,
  [ENVELOPE_ACTION.saveScoreDocs]: STORE_NAME.scoreDocs,
  [ENVELOPE_ACTION.saveStrategySnapshots]: STORE_NAME.strategySnapshots,
  [ENVELOPE_ACTION.saveLocalDocs]: STORE_NAME.localDocs,
  [ENVELOPE_ACTION.saveNews]: STORE_NAME.news,
  [ENVELOPE_ACTION.saveSentimentCache]: STORE_NAME.sentimentCache,
  [ENVELOPE_ACTION.saveResearchLog]: STORE_NAME.researchLogs,
  [ENVELOPE_ACTION.saveScores]: STORE_NAME.v6Scores,
  [ENVELOPE_ACTION.insertOrder]: STORE_NAME.orders,
  [ENVELOPE_ACTION.updateOrder]: STORE_NAME.orders,
  [ENVELOPE_ACTION.deleteOrder]: STORE_NAME.orders,
  [ENVELOPE_ACTION.insertSignal]: STORE_NAME.signals,
  [ENVELOPE_ACTION.saveTradeReview]: STORE_NAME.tradeReviews,
  [ENVELOPE_ACTION.saveExecutionPlan]: STORE_NAME.executionPlans,
  [ENVELOPE_ACTION.updateExecutionPlan]: STORE_NAME.executionPlans,
  [ENVELOPE_ACTION.deleteExecutionPlan]: STORE_NAME.executionPlans,
  [ENVELOPE_ACTION.saveExecutionLog]: STORE_NAME.executionLogs,
  [ENVELOPE_ACTION.saveMissingReport]: STORE_NAME.missingReports,
  [ENVELOPE_ACTION.incrementMissingReportRetry]: STORE_NAME.missingReports,
  [ENVELOPE_ACTION.updateExecutionPhase]: STORE_NAME.executionPlans,
  [ENVELOPE_ACTION.loadHoldingsData]: STORE_NAME.stocks,
  [ENVELOPE_ACTION.savePortfolio]: STORE_NAME.portfolios,
  [ENVELOPE_ACTION.newsArticleLoaded]: STORE_NAME.news,
  [ENVELOPE_ACTION.newsArticleBookmarked]: STORE_NAME.news,
  [ENVELOPE_ACTION.holdingsDataLoaded]: STORE_NAME.stocks,
  [ENVELOPE_ACTION.tradeActionExecuted]: STORE_NAME.orders,
  [ENVELOPE_ACTION.resetAll]: STORE_NAME.stocks,
  [ENVELOPE_ACTION.importAll]: STORE_NAME.stocks,
  [ENVELOPE_ACTION.exportAll]: STORE_NAME.stocks,
  [ENVELOPE_ACTION.strategyHotSectorRefresh]: STORE_NAME.hotSectorScores,
  [ENVELOPE_ACTION.strategyValuePitRefresh]: STORE_NAME.valuePitScores,
  [ENVELOPE_ACTION.strategyRotationSignalDetect]: STORE_NAME.rotationScores,
}

function inferStore(action: string): StoreName {
  const store = ACTION_TO_STORE_MAP[action]
  if (!store) {
    throw new EnvelopeError(`Unknown action: ${action} (no store mapping found)`)
  }
  return store
}

/**
 * 查询请求参数
 */
export interface QueryRequest {
  /** 查询动作：queryGet/queryList/queryByIndex */
  action: typeof ENVELOPE_ACTION.queryGet | typeof ENVELOPE_ACTION.queryList | typeof ENVELOPE_ACTION.queryByIndex
  /** 目标存储 */
  store: StoreName
  /** 主键（queryGet 时必填） */
  key?: string
  /** 索引名（queryByIndex 时必填） */
  indexName?: string
  /** 索引值（queryByIndex 时必填） */
  indexValue?: unknown
  /** 调用模块 */
  source?: ModuleId
}

/**
 * 查询结果
 */
export interface QueryResult<T> {
  success: boolean
  data?: T
  error?: string
}

export class DataBridge {
  private subscribers = new Map<string, Set<EnvelopeCallback>>()
  private fallbackQueue: FallbackQueue = fallbackQueue
  private handlerRegistry: HandlerRegistry = createHandlerRegistry()
  private readCache = new MemoryCache<unknown>({ namespace: 'databridge:read', defaultTTL: 10_000, maxSize: 200 })

  /**
   * 查询数据（读操作）
   * 支持缓存、ACL 校验、审计日志
   */
  async query<T = unknown>(request: QueryRequest): Promise<QueryResult<T>> {
    const startTs = Date.now()
    const source = request.source ?? ('datalayer' as ModuleId)
    logger.info(`[DataBridge] query() called: action="${request.action}", store="${request.store}", source="${source}", key="${request.key ?? 'N/A'}", indexName="${request.indexName ?? 'N/A'}"`)

    try {
      // 1. 生成缓存 key
      const cacheKey = this.buildCacheKey(request)
      logger.debug(`[DataBridge] query() cache key generated: "${cacheKey}"`)

      // 2. 查缓存
      const cached = this.readCache.get(cacheKey) as T | undefined
      if (cached !== undefined) {
        const cacheStats = this.readCache.getStats()
        logger.info(`[DataBridge] query() cache HIT: key="${cacheKey}", cacheSize=${cacheStats.size}, hitRate=${(cacheStats.hitRate * 100).toFixed(1)}%`)
        const duration = Date.now() - startTs
        logger.info(`[DataBridge] query() completed (from cache): action="${request.action}", store="${request.store}", duration=${duration}ms`)
        return { success: true, data: cached }
      }
      logger.info(`[DataBridge] query() cache MISS: key="${cacheKey}", proceeding to database query`)

      // 3. ACL 校验
      try {
        logger.debug(`[DataBridge] query() ACL check starting: module="${source}", store="${request.store}", operation="SELECT"`)
        aclEngine.assert({
          module: source,
          store: request.store,
          operation: 'SELECT',
        })
        logger.info(`[DataBridge] query() ACL check PASSED: module="${source}", store="${request.store}", operation="SELECT"`)
      } catch (aclErr) {
        const aclErrorMessage = aclErr instanceof Error ? aclErr.message : String(aclErr)
        logger.error(`[DataBridge] query() ACL check FAILED: module="${source}", store="${request.store}", operation="SELECT", reason="${aclErrorMessage}"`)
        throw aclErr
      }

      // 4. 执行数据库操作
      logger.debug(`[DataBridge] query() executing database operation: action="${request.action}", store="${request.store}"`)
      let result: T
      switch (request.action) {
        case ENVELOPE_ACTION.queryGet: {
          if (!request.key) {
            logger.error(`[DataBridge] query() parameter validation failed: queryGet requires key parameter`)
            throw new EnvelopeError('queryGet requires key parameter')
          }
          logger.debug(`[DataBridge] query() executing db.get: store="${request.store}", key="${request.key}"`)
          result = await db.get(request.store, request.key) as T
          logger.debug(`[DataBridge] query() db.get completed: found=${result !== undefined && result !== null}`)
          break
        }
        case ENVELOPE_ACTION.queryList: {
          logger.debug(`[DataBridge] query() executing db.getAll: store="${request.store}"`)
          result = await db.getAll(request.store) as T
          const listLength = Array.isArray(result) ? result.length : 'N/A'
          logger.debug(`[DataBridge] query() db.getAll completed: resultCount=${listLength}`)
          break
        }
        case ENVELOPE_ACTION.queryByIndex: {
          if (!request.indexName || request.indexValue === undefined) {
            logger.error(`[DataBridge] query() parameter validation failed: queryByIndex requires indexName and indexValue parameters`)
            throw new EnvelopeError('queryByIndex requires indexName and indexValue parameters')
          }
          const indexValueStr = typeof request.indexValue === 'string' ? request.indexValue : JSON.stringify(request.indexValue)
          logger.debug(`[DataBridge] query() executing db.getAllByIndex: store="${request.store}", indexName="${request.indexName}", indexValue="${indexValueStr}"`)
          result = await db.getAllByIndex(request.store, request.indexName, request.indexValue as string) as T
          const indexListLength = Array.isArray(result) ? result.length : 'N/A'
          logger.debug(`[DataBridge] query() db.getAllByIndex completed: resultCount=${indexListLength}`)
          break
        }
        default: {
          const unknownAction: string = request.action as string
          logger.error(`[DataBridge] query() unknown action: "${unknownAction}"`)
          throw new EnvelopeError(`Unknown query action: ${unknownAction}`)
        }
      }

      // 5. 缓存结果
      this.readCache.set(cacheKey, result)
      const cacheStatsAfterSet = this.readCache.getStats()
      logger.info(`[DataBridge] query() result cached: key="${cacheKey}", cacheSize=${cacheStatsAfterSet.size}, maxSize=${cacheStatsAfterSet.maxSize}`)

      // 6. 审计日志
      this.writeQueryAuditLog(request, source).catch((err) => {
        logger.error(`[DataBridge] query() audit log failed: action="${request.action}", store="${request.store}", traceId="query-${Date.now()}"`, { error: err })
      })

      const duration = Date.now() - startTs
      logger.info(`[DataBridge] query() completed (from db): action="${request.action}", store="${request.store}", duration=${duration}ms`)

      return { success: true, data: result }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      const errorName = err instanceof Error ? err.name : 'UnknownError'
      logger.error(`[DataBridge] query() FAILED: action="${request.action}", store="${request.store}", errorName="${errorName}", errorMessage="${message}"`)
      return { success: false, error: message }
    }
  }

  /**
   * 清除指定 store 的缓存
   * 在写操作后调用，保证数据一致性
   */
  invalidateCache(store: StoreName): void {
    const statsBefore = this.readCache.getStats()
    logger.info(`[DataBridge] invalidateCache() called: store="${store}", cacheSizeBefore=${statsBefore.size}, hitCount=${statsBefore.hitCount}, missCount=${statsBefore.missCount}`)
    // MemoryCache 不支持批量删除，只能 clear 全部
    // 后续可优化为按 pattern 删除
    this.readCache.clear()
    const statsAfter = this.readCache.getStats()
    logger.info(`[DataBridge] invalidateCache() completed: store="${store}", cacheSizeAfter=${statsAfter.size}, clearedEntries=${statsBefore.size - statsAfter.size}`)
  }

  private buildCacheKey(request: QueryRequest): string {
    const parts: string[] = [request.action, request.store]
    if (request.key) parts.push(`key=${request.key}`)
    if (request.indexName) parts.push(`idx=${request.indexName}`)
    if (request.indexValue !== undefined) {
      const valStr = typeof request.indexValue === 'string' ? request.indexValue : JSON.stringify(request.indexValue)
      parts.push(`val=${valStr}`)
    }
    return parts.join(':')
  }

  private async writeQueryAuditLog(request: QueryRequest, source: ModuleId): Promise<void> {
    const targetCode = request.key ?? request.indexValue?.toString() ?? request.action
    await db.put(STORE_NAME.researchLogs, {
      traceId: `query-${Date.now()}`,
      timestamp: Date.now(),
      actor: source,
      action: request.action,
      targetType: request.store,
      targetCode,
      payload: JSON.stringify({ indexName: request.indexName }),
    })
  }

  async forward(envelope: StandardEnvelope): Promise<void> {
    const startTs = Date.now()
    logger.info(`[DataBridge] forward() called: action="${envelope.meta.action}", source="${envelope.meta.source}", traceId="${envelope.meta.traceId}"`)

    const validation = EnvelopeFactory.validate(envelope)
    if (!validation.valid) {
      logger.error(`[DataBridge] Invalid envelope: ${validation.error}, action="${envelope.meta.action}"`)
      throw new EnvelopeError(`Invalid envelope: ${validation.error}`)
    }
    logger.debug(`[DataBridge] Envelope validated: action="${envelope.meta.action}", target="${envelope.meta.target}"`)

    const { meta } = envelope
    const targetStore = inferStore(meta.action)
    const operation = inferOperation(meta.action)

    logger.debug(`[DataBridge] Route determined: action="${meta.action}", targetStore="${targetStore}", operation="${operation}"`)

    try {
      try {
        aclEngine.assert({
          module: meta.source as ModuleId,
          store: targetStore,
          operation,
        })
        logger.debug(`[DataBridge] ACL check passed: module="${meta.source}", store="${targetStore}", operation="${operation}"`)
      } catch (aclErr) {
        logger.error(`[DataBridge] ACL check failed: module="${meta.source}", store="${targetStore}", operation="${operation}"`, { error: aclErr })
        if (this.isMarketEnvelope(meta.action)) {
          logger.warn(`[DataBridge] ACL rejected market envelope, enqueueing for retry: action="${meta.action}", traceId="${meta.traceId}"`)
          this.fallbackQueue.push(envelope)
          return
        }
        throw aclErr
      }

      this.writeAuditLog(envelope, targetStore).catch((err) => {
        logger.error(`[DataBridge] Audit log failed: action="${meta.action}", traceId="${meta.traceId}"`, { error: err })
      })

      if (
        meta.action === ENVELOPE_ACTION.strategyHotSectorRefresh ||
        meta.action === ENVELOPE_ACTION.strategyValuePitRefresh ||
        meta.action === ENVELOPE_ACTION.strategyRotationSignalDetect
      ) {
        logger.info(`[DataBridge] Routing to strategy engine: action="${meta.action}"`)
        await this.routeToStrategy(envelope)
        return
      }

      if (
        meta.action === ENVELOPE_ACTION.resetAll ||
        meta.action === ENVELOPE_ACTION.importAll ||
        meta.action === ENVELOPE_ACTION.exportAll
      ) {
        logger.info(`[DataBridge] Routing to manager: action="${meta.action}"`)
        await this.routeToManager(envelope)
      } else {
        logger.info(`[DataBridge] Routing to DB: action="${meta.action}", store="${targetStore}"`)
        await this.routeToDB(envelope, targetStore)
      }

      // 写操作成功后清除相关缓存，保证读一致性
      this.invalidateCache(targetStore)

      logger.debug(`[DataBridge] Broadcasting to channel: "${targetStore}"`)
      this.broadcast(targetStore, envelope)
    } catch (err) {
      logger.error(`[DataBridge] forward() failed: action="${meta.action}", traceId="${meta.traceId}"`, { error: err })
      throw err
    } finally {
      const duration = Date.now() - startTs
      if (duration > FORWARD_SLOW_THRESHOLD_MS) {
        logger.warn(`[DataBridge] forward() took ${duration}ms for action "${meta.action}"`)
      }
      logger.info(`[DataBridge] forward() completed: action="${meta.action}", duration=${duration}ms`)
    }
  }

  subscribe(channel: string, callback: EnvelopeCallback): () => void {
    logger.debug(`[DataBridge] subscribe() called: channel="${channel}"`)

    if (channel === 'db') {
      logger.error(`[DataBridge] subscribe() rejected: cannot subscribe to "db" channel`)
      throw new EnvelopeError('Cannot subscribe to "db" channel')
    }

    if (!this.subscribers.has(channel)) {
      this.subscribers.set(channel, new Set())
      logger.debug(`[DataBridge] Created subscriber set for channel: "${channel}"`)
    }

    const prevCount = this.subscribers.get(channel)!.size
    this.subscribers.get(channel)!.add(callback)
    const newCount = this.subscribers.get(channel)!.size

    logger.info(`[DataBridge] Subscribe: channel="${channel}", count=${prevCount}→${newCount}`)

    return () => {
      const wasPresent = this.subscribers.get(channel)?.has(callback)
      this.subscribers.get(channel)?.delete(callback)
      const remaining = this.subscribers.get(channel)?.size ?? 0

      if (wasPresent) {
        logger.info(`[DataBridge] Unsubscribe: channel="${channel}", remaining=${remaining}`)
      }
    }
  }

  private isMarketEnvelope(action: string): boolean {
    return action === ENVELOPE_ACTION.saveDailyQuotes
  }

  get failedEnvelopes(): readonly StandardEnvelope[] {
    return this.fallbackQueue.peek()
  }

  async retryFailed(): Promise<{ success: number; failed: number }> {
    const pending = this.fallbackQueue.drain()
    let success = 0
    let failed = 0

    for (const envelope of pending) {
      try {
        await this.forward(envelope)
        success++
        logger.info(`[DataBridge] Retry succeeded: action="${envelope.meta.action}", traceId="${envelope.meta.traceId}"`)
      } catch (err) {
        failed++
        logger.warn(`[DataBridge] Retry failed, re-enqueueing: action="${envelope.meta.action}", traceId="${envelope.meta.traceId}"`, { error: err })
        this.fallbackQueue.push(envelope)
      }
    }

    return { success, failed }
  }

  private async routeToDB(
    envelope: StandardEnvelope,
    store: StoreName,
  ): Promise<void> {
    const startTs = Date.now()
    const { meta } = envelope
    logger.debug(`[DataBridge] routeToDB() called: action="${meta.action}", store="${store}"`)

    try {
      // 使用策略模式：查找对应的 Handler
      const handler = this.handlerRegistry.findHandler(meta.action)
      if (!handler) {
        logger.warn(`[DataBridge] No handler found for action: "${meta.action}", falling back to default put`)
        await db.put(store, envelope.payload)
      } else {
        await handler.handle(envelope, store)
      }

      const duration = Date.now() - startTs
      logger.info(`[DataBridge] routeToDB() completed: action="${meta.action}", store="${store}", duration=${duration}ms`)
    } catch (err) {
      logger.error(`[DataBridge] routeToDB() failed: action="${meta.action}", store="${store}"`, { error: err })
      throw new EnvelopeError(
        `DB route failed for ${store}: ${err instanceof Error ? err.message : String(err)}`,
      )
    }
  }

  private async routeToManager(envelope: StandardEnvelope): Promise<void> {
    const startTs = Date.now()
    const { meta } = envelope
    logger.debug(`[DataBridge] routeToManager() called: action="${meta.action}"`)

    try {
      switch (meta.action) {
        case ENVELOPE_ACTION.resetAll: {
          logger.info(`[DataBridge] Manager resetAll: clearing entire database`)
          await db.reset()
          break
        }
        case ENVELOPE_ACTION.importAll: {
          const data = envelope.payload as Record<string, unknown[]>
          const tableCount = Object.keys(data).length
          const totalRecords = Object.values(data).reduce((sum, arr) => sum + arr.length, 0)
          logger.info(`[DataBridge] Manager importAll: ${tableCount} tables, ${totalRecords} records`)
          await db.import(data)
          break
        }
        case ENVELOPE_ACTION.exportAll: {
          logger.info(`[DataBridge] Manager exportAll: exporting all data`)
          await db.export()
          break
        }
        default: {
          logger.error(`[DataBridge] routeToManager() failed: Unknown action "${meta.action}"`)
          throw new EnvelopeError(`Unknown manager action: ${envelope.meta.action}`)
        }
      }

      const duration = Date.now() - startTs
      logger.info(`[DataBridge] routeToManager() completed: action="${meta.action}", duration=${duration}ms`)
    } catch (err) {
      logger.error(`[DataBridge] routeToManager() failed: action="${meta.action}"`, { error: err })
      throw err
    }
  }

  private async routeToStrategy(envelope: StandardEnvelope): Promise<void> {
    const startTs = Date.now()
    const { meta, payload } = envelope
    logger.info(`[DataBridge] routeToStrategy() called: action="${meta.action}"`)

    try {
      switch (meta.action) {
        case ENVELOPE_ACTION.strategyHotSectorRefresh: {
          try {
            // ===== 1. 输入校验 =====
            const inputs = payload as HotSectorAnalyzerInput[]
            if (!Array.isArray(inputs)) {
              const err = new EnvelopeError('HotSector: payload 必须是数组')
              logger.error(`[DataBridge] HotSector refresh: payload 校验失败`, { error: err })
              throw err
            }
            logger.info(`[DataBridge] HotSector refresh: 输入数量=${inputs.length}, 板块列表=[${inputs.map((i) => i.symbol).join(', ')}]`)

            // ===== 2. 逐板块评分 =====
            const scores = inputs.map((input) => {
              const score = analyzeHotSector(input)
              logger.info(
                `[DataBridge] HotSector: ${input.symbol} ` +
                `momentum=${score.dimensions.momentum.toFixed(2)} ` +
                `sentiment=${score.dimensions.sentiment.toFixed(2)} ` +
                `technical=${score.dimensions.technical.toFixed(2)} ` +
                `valuation=${score.dimensions.valuation.toFixed(2)} ` +
                `marketEnv=${(score.dimensions.marketEnv ?? 0).toFixed(2)} ` +
                `→ score=${score.score.toFixed(2)} action=${score.action}`,
              )
              return score
            })

            // ===== 3. 评分汇总 =====
            const avgScore = scores.reduce((s, c) => s + c.score, 0) / scores.length
            const maxScore = Math.max(...scores.map((s) => s.score))
            const minScore = Math.min(...scores.map((s) => s.score))
            const immediateCount = scores.filter((s) => s.action === 'immediate').length
            const probeCount = scores.filter((s) => s.action === 'probe').length
            const ignoreCount = scores.filter((s) => s.action === 'ignore').length
            logger.info(
              `[DataBridge] HotSector 评分汇总: ` +
              `avg=${avgScore.toFixed(2)} max=${maxScore.toFixed(2)} min=${minScore.toFixed(2)} ` +
              `immediate=${immediateCount} probe=${probeCount} ignore=${ignoreCount}`,
            )

            // ===== 4. 广播到策略频道 =====
            const subscriberCount = this.subscribers.get(STRATEGY_CHANNEL.hotSector)?.size ?? 0
            logger.info(`[DataBridge] HotSector: 准备广播到 channel="${STRATEGY_CHANNEL.hotSector}", 订阅者数=${subscriberCount}`)

            const channelEnvelope: StandardEnvelope = {
              ...envelope,
              payload: scores,
              meta: { ...meta, target: STRATEGY_CHANNEL.hotSector as EnvelopeTarget },
            }
            this.broadcast(STRATEGY_CHANNEL.hotSector, channelEnvelope)
            logger.info(`[DataBridge] HotSector: channel="${STRATEGY_CHANNEL.hotSector}" 广播完成`)

            // ===== 5. EventBus 事件 =====
            eventBus.emit(EVENT_NAMES.HOT_SECTOR_CHANGED, scores)
            logger.info(`[DataBridge] HotSector: EventBus emit "${EVENT_NAMES.HOT_SECTOR_CHANGED}" 完成, payload.length=${scores.length}`)
          } catch (err) {
            logger.error(`[DataBridge] HotSector refresh 失败`, { error: err })
            throw err
          }
          break
        }

        case ENVELOPE_ACTION.strategyValuePitRefresh: {
          try {
            // ===== 1. 输入校验 =====
            const inputs = payload as ValuePitAnalyzerInput[]
            if (!Array.isArray(inputs)) {
              const err = new EnvelopeError('ValuePit: payload 必须是数组')
              logger.error(`[DataBridge] ValuePit refresh: payload 校验失败`, { error: err })
              throw err
            }
            logger.info(`[DataBridge] ValuePit refresh: 输入数量=${inputs.length}, 板块列表=[${inputs.map((i) => i.symbol).join(', ')}]`)

            // ===== 2. 逐板块评分 =====
            const scores = inputs.map((input) => {
              const score = analyzeValuePit(input)
              logger.info(
                `[DataBridge] ValuePit: ${input.symbol} ` +
                `catalyst=${score.dimensions.catalyst.toFixed(2)} ` +
                `valuation=${score.dimensions.valuation.toFixed(2)} ` +
                `chip=${score.dimensions.chip.toFixed(2)} ` +
                `rotation=${score.dimensions.rotation.toFixed(2)} ` +
                `liquidity=${score.dimensions.liquidity.toFixed(2)} ` +
                `→ score=${score.score.toFixed(2)} action=${score.action}`,
              )
              return score
            })

            // ===== 3. 评分汇总 =====
            const avgScore = scores.reduce((s, c) => s + c.score, 0) / scores.length
            const maxScore = Math.max(...scores.map((s) => s.score))
            const minScore = Math.min(...scores.map((s) => s.score))
            const immediateCount = scores.filter((s) => s.action === 'immediate').length
            const probeCount = scores.filter((s) => s.action === 'probe').length
            const waitCount = scores.filter((s) => s.action === 'wait').length
            const ignoreCount = scores.filter((s) => s.action === 'ignore').length
            logger.info(
              `[DataBridge] ValuePit 评分汇总: ` +
              `avg=${avgScore.toFixed(2)} max=${maxScore.toFixed(2)} min=${minScore.toFixed(2)} ` +
              `immediate=${immediateCount} probe=${probeCount} wait=${waitCount} ignore=${ignoreCount}`,
            )

            // ===== 4. 广播到策略频道 =====
            const subscriberCount = this.subscribers.get(STRATEGY_CHANNEL.valuePit)?.size ?? 0
            logger.info(`[DataBridge] ValuePit: 准备广播到 channel="${STRATEGY_CHANNEL.valuePit}", 订阅者数=${subscriberCount}`)

            const channelEnvelope: StandardEnvelope = {
              ...envelope,
              payload: scores,
              meta: { ...meta, target: STRATEGY_CHANNEL.valuePit as EnvelopeTarget },
            }
            this.broadcast(STRATEGY_CHANNEL.valuePit, channelEnvelope)
            logger.info(`[DataBridge] ValuePit: channel="${STRATEGY_CHANNEL.valuePit}" 广播完成`)

            // ===== 5. EventBus 事件 =====
            eventBus.emit(EVENT_NAMES.VALUE_PIT_CHANGED, scores)
            logger.info(`[DataBridge] ValuePit: EventBus emit "${EVENT_NAMES.VALUE_PIT_CHANGED}" 完成, payload.length=${scores.length}`)
          } catch (err) {
            logger.error(`[DataBridge] ValuePit refresh 失败`, { error: err })
            throw err
          }
          break
        }

        case ENVELOPE_ACTION.strategyRotationSignalDetect: {
          try {
            // ===== 1. 输入校验 =====
            const inputs = payload as RotationSignalInput[]
            if (!Array.isArray(inputs)) {
              const err = new EnvelopeError('RotationSignal: payload 必须是数组')
              logger.error(`[DataBridge] RotationSignal detect: payload 校验失败`, { error: err })
              throw err
            }
            logger.info(
              `[DataBridge] RotationSignal detect: 输入数量=${inputs.length}, ` +
              `板块列表=[${inputs.map((i) => i.sectorId).join(', ')}], ` +
              `成交量数据量=[${inputs.map((i) => i.volume.history.length).join(', ')}], ` +
              `资金流数据量=[${inputs.map((i) => i.capitalFlow.dailyNetFlow.length).join(', ')}], ` +
              `收盘价数据量=[${inputs.map((i) => i.goldenCross.closes.length).join(', ')}]`,
            )

            // ===== 2. 逐板块检测 =====
            const signals = inputs.map((input) => {
              const signal = detectRotation(input)
              logger.info(
                `[DataBridge] RotationSignal: ${input.sectorId} ` +
                `volumeBreakthrough=${signal.conditions.volumeBreakthrough} ` +
                `capitalInflow=${signal.conditions.capitalInflow} ` +
                `goldenCross=${signal.conditions.goldenCross} ` +
                `→ triggered=${signal.triggered} strength=${signal.strength}`,
              )
              return signal
            })

            // ===== 3. 检测汇总 =====
            const triggeredCount = signals.filter((s) => s.triggered).length
            const notTriggeredCount = signals.length - triggeredCount
            const strongCount = signals.filter((s) => s.strength === 'strong').length
            const mediumCount = signals.filter((s) => s.strength === 'medium').length
            const weakCount = signals.filter((s) => s.strength === 'weak').length
            const triggeredList = signals.filter((s) => s.triggered).map((s) => s.sectorId)
            logger.info(
              `[DataBridge] RotationSignal 检测汇总: ` +
              `总=${signals.length} 触发=${triggeredCount} 未触发=${notTriggeredCount} ` +
              `strong=${strongCount} medium=${mediumCount} weak=${weakCount} ` +
              `触发板块=[${triggeredList.join(', ') || '无'}]`,
            )

            // ===== 4. 广播到策略频道 =====
            const subscriberCount = this.subscribers.get(STRATEGY_CHANNEL.rotationSignal)?.size ?? 0
            logger.info(`[DataBridge] RotationSignal: 准备广播到 channel="${STRATEGY_CHANNEL.rotationSignal}", 订阅者数=${subscriberCount}`)

            const channelEnvelope: StandardEnvelope = {
              ...envelope,
              payload: signals,
              meta: { ...meta, target: STRATEGY_CHANNEL.rotationSignal as EnvelopeTarget },
            }
            this.broadcast(STRATEGY_CHANNEL.rotationSignal, channelEnvelope)
            logger.info(`[DataBridge] RotationSignal: channel="${STRATEGY_CHANNEL.rotationSignal}" 广播完成`)

            // ===== 5. EventBus 事件 =====
            eventBus.emit(EVENT_NAMES.ROTATION_SIGNAL_TRIGGERED, signals)
            logger.info(`[DataBridge] RotationSignal: EventBus emit "${EVENT_NAMES.ROTATION_SIGNAL_TRIGGERED}" 完成, payload.length=${signals.length}`)
          } catch (err) {
            logger.error(`[DataBridge] RotationSignal detect 失败`, { error: err })
            throw err
          }
          break
        }

        default: {
          logger.error(`[DataBridge] routeToStrategy() failed: Unknown action "${meta.action}"`)
          throw new EnvelopeError(`Unknown strategy action: ${meta.action}`)
        }
      }

      const duration = Date.now() - startTs
      logger.info(`[DataBridge] routeToStrategy() completed: action="${meta.action}", duration=${duration}ms`)
    } catch (err) {
      logger.error(`[DataBridge] routeToStrategy() failed: action="${meta.action}"`, { error: err })
      throw err
    }
  }

  private async writeAuditLog(
    envelope: StandardEnvelope,
    store: StoreName,
  ): Promise<void> {
    const { meta, payload } = envelope
    const targetCode =
      payload && typeof payload === 'object' && 'symbol' in payload
        ? String((payload as Record<string, unknown>).symbol)
        : String(meta.action)

    logger.debug(`[DataBridge] writeAuditLog(): action="${meta.action}", targetType="${store}", targetCode="${targetCode}"`)

    await db.put(STORE_NAME.researchLogs, {
      traceId: meta.traceId,
      timestamp: Date.now(),
      actor: meta.source,
      action: meta.action,
      targetType: store,
      targetCode,
      payload: JSON.stringify(payload),
    })
  }

  private broadcast(channel: string, envelope: StandardEnvelope): void {
    const startTs = Date.now()
    logger.debug(`[DataBridge] broadcast() called: channel="${channel}", action="${envelope.meta.action}"`)

    const callbacks = this.subscribers.get(channel)
    if (!callbacks) {
      logger.debug(`[DataBridge] broadcast() skipped: no subscribers for channel "${channel}"`)
      return
    }

    const callbackCount = callbacks.size
    let successCount = 0
    let errorCount = 0
    let subscriberIndex = 0

    callbacks.forEach((cb) => {
      subscriberIndex++
      try {
        cb(envelope)
        successCount++
      } catch (err) {
        errorCount++
        logger.error(`[DataBridge] Subscriber #${subscriberIndex} error for channel "${channel}"`, { error: err })
      }
    })

    logger.info(`[DataBridge] broadcast() to subscribers: channel="${channel}", listeners=${callbackCount}, success=${successCount}, errors=${errorCount}`)

    const eventName = `${channel}${CHANGED_SUFFIX}`
    logger.debug(`[DataBridge] Emitting eventBus: "${eventName}"`)
    try {
      eventBus.emit(eventName, envelope)
    } catch (err) {
      logger.warn(`[DataBridge] eventBus.emit failed for channel "${channel}", action="${envelope.meta.action}", traceId="${envelope.meta.traceId}"`, { error: err })
    }

    const duration = Date.now() - startTs
    if (duration > BROADCAST_SLOW_THRESHOLD_MS) {
      logger.warn(`[DataBridge] broadcast() took ${duration}ms for channel "${channel}"`)
    }
  }
}

export const dataBridge = new DataBridge()

/**
 * @module dataflowEngine
 * @lifecycle @Global
 * @description 数据流引擎。提供发布-订阅模式的数据流分发，支持缓存、优先级调度和重连。
 *
 * @remarks
 * - 支持 SSE 实时推送和轮询两种模式
 * - 缓存支持 TTL 过期和 LRU 容量淘汰
 * - 订阅者按 channel 的 priority 优先级分发
 *
 * @see src/core/dataflow/dataflowTypes.ts
 * @see src/core/dataflow/defaultDataBuilder.ts
 */

import { getLogger } from '@/lib/logger'
import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { defaultDataBuilder } from './defaultDataBuilder'
import type { DataPacket, ChannelMeta, DataChannel, CacheStats } from './dataflowTypes'

const logger = getLogger()

type DataCallback<T = unknown> = (packet: DataPacket<T>) => void

const DEFAULT_CACHE_MAX_ENTRIES = 100
const DEFAULT_TTL_MULTIPLIER = 3

const PRIORITY_ORDER: Record<string, number> = {
  high: 0,
  normal: 1,
  low: 2,
}

const DEFAULT_CHANNELS: ChannelMeta[] = [
  { channel: 'market:index', description: '大盘指数实时数据', refreshInterval: 5000, persist: true, priority: 'high' },
  { channel: 'market:sector', description: '板块涨跌排行', refreshInterval: 10000, persist: true, priority: 'high' },
  { channel: 'market:fundflow', description: '资金流向统计', refreshInterval: 15000, persist: true, priority: 'normal' },
  { channel: 'market:emotion', description: '市场情绪指标', refreshInterval: 30000, persist: false, priority: 'low' },
  { channel: 'portfolio:summary', description: '持仓总览', refreshInterval: 10000, persist: true, priority: 'high' },
  { channel: 'portfolio:holding', description: '持仓明细', refreshInterval: 30000, persist: true, priority: 'normal' },
  { channel: 'strategy:signal', description: '买卖信号', refreshInterval: 5000, persist: false, priority: 'high' },
  { channel: 'strategy:score', description: '股票评分', refreshInterval: 60000, persist: true, priority: 'normal' },
  { channel: 'agent:status', description: 'Agent状态', refreshInterval: 10000, persist: false, priority: 'normal' },
  { channel: 'system:health', description: '系统健康', refreshInterval: 30000, persist: false, priority: 'low' },
]

interface CacheEntry {
  data: unknown
  timestamp: number
  seq: number
  channel: string
  lastAccessAt: number
}

export class DataFlowEngine {
  private subscribers = new Map<string, Set<DataCallback>>()
  private cache = new Map<string, CacheEntry>()
  private cacheMaxEntries = DEFAULT_CACHE_MAX_ENTRIES
  private cacheStats: CacheStats = {
    hits: 0,
    misses: 0,
    size: 0,
    totalRequests: 0,
    totalEntries: 0,
    maxEntries: DEFAULT_CACHE_MAX_ENTRIES,
    hitRate: 0,
    hitCount: 0,
    missCount: 0,
    expiredCount: 0,
    evictedCount: 0,
  }
  private channelMeta = new Map<string, ChannelMeta>()
  private eventSource: EventSource | null = null
  private connected = false
  private seqCounter = 0
  private connectionListeners = new Set<(connected: boolean) => void>()
  private refreshTimers = new Map<string, ReturnType<typeof setInterval>>()
  private reconnectAttempts = 0
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null
  private readonly maxReconnectDelay = 30000
  private readonly maxReconnectAttempts = 5

  constructor() {
    logger.info('[DataFlowEngine] Initializing...')
    DEFAULT_CHANNELS.forEach((c) => {
      const meta = defaultDataBuilder.buildChannelMeta(c.channel)
      this.channelMeta.set(c.channel, { ...meta, ttl: meta.ttl ?? meta.refreshInterval * DEFAULT_TTL_MULTIPLIER })
      logger.debug(`[DataFlowEngine] Registered channel: ${c.channel} (${c.priority}, ${c.refreshInterval}ms)`)
    })
    logger.info(`[DataFlowEngine] Initialized with ${this.channelMeta.size} default channels`)
  }

  connect(url?: string): void {
    if (this.connected) {
      logger.debug('[DataFlowEngine] connect() skipped - already connected')
      return
    }
    logger.info(`[DataFlowEngine] connect() called, url=${url ?? 'none (polling mode)'}`)

    if (url && typeof EventSource !== 'undefined') {
      logger.debug('[DataFlowEngine] Attempting SSE connection...')
      try {
        this.eventSource = new EventSource(url)
        this.eventSource.onopen = () => {
          this.connected = true
          this.reconnectAttempts = 0
          if (this.reconnectTimer) {
            clearTimeout(this.reconnectTimer)
            this.reconnectTimer = null
          }
          logger.info('[DataFlowEngine] SSE connection established successfully')
          eventBus.emit(EVENT_NAMES.DATAFLOW_CONNECTED, { connected: true })
          this._notifyConnectionChange(true)
        }
        this.eventSource.onmessage = (event) => {
          logger.debug(`[DataFlowEngine] SSE message received, length=${event.data.length}`)
          try {
            const packet = JSON.parse(event.data as string) as DataPacket
            if (packet.channel) {
              logger.debug(`[DataFlowEngine] Parsed packet: channel=${packet.channel}, seq=${packet.seq}`)
              this._distribute(packet)
            } else {
              logger.warn('[DataFlowEngine] Invalid packet: missing channel field')
            }
          } catch (parseErr) {
            logger.error('[DataFlowEngine] Failed to parse SSE message', { error: parseErr })
          }
        }
        this.eventSource.onerror = () => {
          this.connected = false
          logger.warn('[DataFlowEngine] SSE connection error')
          eventBus.emit(EVENT_NAMES.DATAFLOW_DISCONNECTED, { connected: false })
          this._notifyConnectionChange(false)
          this._scheduleReconnect(url)
        }
      } catch (connErr) {
        logger.warn('[DataFlowEngine] SSE connection failed, switching to polling mode', { error: connErr })
        this.connected = true
        eventBus.emit(EVENT_NAMES.DATAFLOW_CONNECTED, { connected: true })
        this._notifyConnectionChange(true)
      }
    } else {
      logger.info('[DataFlowEngine] Running in polling mode (EventSource not available or no URL)')
      this.connected = true
      eventBus.emit(EVENT_NAMES.DATAFLOW_CONNECTED, { connected: true })
      this._notifyConnectionChange(true)
    }
  }

  disconnect(): void {
    logger.info('[DataFlowEngine] disconnect() called')
    this.connected = false
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }
    this.reconnectAttempts = 0
    if (this.eventSource) {
      logger.debug('[DataFlowEngine] Closing SSE connection')
      this.eventSource.close()
      this.eventSource = null
    }
    this.refreshTimers.forEach((timer, channel) => {
      clearInterval(timer)
      logger.debug(`[DataFlowEngine] Cleared refresh timer for channel: ${channel}`)
    })
    this.refreshTimers.clear()
    logger.info(`[DataFlowEngine] Disconnected. Cleared ${this.refreshTimers.size} refresh timers`)
    eventBus.emit(EVENT_NAMES.DATAFLOW_DISCONNECTED, { connected: false })
    this._notifyConnectionChange(false)
  }

  subscribe<T>(channel: string, callback: DataCallback<T>): () => void {
    logger.debug(`[DataFlowEngine] subscribe() called, channel="${channel}"`)

    if (!this.channelMeta.has(channel)) {
      logger.warn(`[DataFlowEngine] Subscribe to unknown channel: "${channel}"`)
    }

    if (!this.subscribers.has(channel)) {
      this.subscribers.set(channel, new Set())
      logger.debug(`[DataFlowEngine] Created subscriber set for new channel: "${channel}"`)
    }

    const typedCallback = callback as DataCallback
    const prevCount = this.subscribers.get(channel)!.size
    this.subscribers.get(channel)!.add(typedCallback)
    const newCount = this.subscribers.get(channel)!.size

    logger.info(`[DataFlowEngine] Subscribe: channel="${channel}", count=${prevCount}→${newCount}`)

    const cached = this.getCached<T>(channel)
    if (cached) {
      logger.debug(`[DataFlowEngine] Found cached data for "${channel}", seq=${cached.seq}`)
      queueMicrotask(() => {
        try {
          logger.debug(`[DataFlowEngine] Delivering cached data to subscriber for "${channel}"`)
          typedCallback(cached)
        } catch (err) {
          logger.error(`[DataFlowEngine] Cache callback error for channel "${channel}"`, { error: err })
        }
      })
    } else {
      logger.debug(`[DataFlowEngine] No cached data for "${channel}"`)
    }

    return () => {
      this.subscribers.get(channel)?.delete(typedCallback)
      const remaining = this.subscribers.get(channel)?.size ?? 0
      logger.info(`[DataFlowEngine] Unsubscribe: channel="${channel}", remaining=${remaining}`)

      if (remaining === 0) {
        logger.debug(`[DataFlowEngine] Last subscriber removed from "${channel}", stopping refresh`)
        this.stopRefresh(channel)
      }
    }
  }

  getCached<T>(channel: string): DataPacket<T> | undefined {
    const entry = this.cache.get(channel)
    if (!entry) {
      this.cacheStats.missCount++
      return undefined
    }

    const meta = this.channelMeta.get(channel)
    const ttl = meta?.ttl

    if (ttl && Date.now() - entry.timestamp > ttl) {
      this.cache.delete(channel)
      this.cacheStats.expiredCount++
      this.cacheStats.totalEntries = this.cache.size
      logger.debug(`[DataFlowEngine] Cache expired: channel="${channel}", age=${Date.now() - entry.timestamp}ms`)
      return undefined
    }

    entry.lastAccessAt = Date.now()
    this.cacheStats.hitCount++
    return {
      channel: channel as DataChannel,
      data: entry.data as T,
      timestamp: entry.timestamp,
      seq: entry.seq,
    }
  }

  publish<T>(channel: string, data: T): void {
    const startTs = Date.now()
    this.seqCounter++
    const packet: DataPacket<T> = { channel: channel as DataChannel, data, timestamp: Date.now(), seq: this.seqCounter }
    const meta = this.channelMeta.get(channel)

    if (!meta) {
      logger.warn(`[DataFlowEngine] Publish to unknown channel: "${channel}"`)
    }

    if (!meta || meta.persist) {
      this.cache.set(channel, {
        data,
        timestamp: packet.timestamp,
        seq: packet.seq,
        channel,
        lastAccessAt: Date.now(),
      })
      this.cacheStats.totalEntries = this.cache.size
      this._evictIfNeeded()
      logger.debug(`[DataFlowEngine] Cache updated: channel="${channel}", seq=${packet.seq}, persist=${meta?.persist ?? 'default'}`)
    }

    logger.info(`[DataFlowEngine] Publish: channel="${channel}", seq=${packet.seq}, payloadSize=${JSON.stringify(data).length}`)
    eventBus.emit(EVENT_NAMES.DATAFLOW_PACKET_PUBLISHED, { channel, seq: packet.seq })

    this._distribute(packet)
    const duration = Date.now() - startTs
    if (duration > 10) {
      logger.warn(`[DataFlowEngine] Publish took ${duration}ms for channel "${channel}"`)
    }
  }

  private _evictIfNeeded(): void {
    if (this.cache.size <= this.cacheMaxEntries) return

    const entries = Array.from(this.cache.values())
      .sort((a, b) => a.lastAccessAt - b.lastAccessAt)

    const toEvict = entries.slice(0, this.cache.size - this.cacheMaxEntries)
    for (const entry of toEvict) {
      this.cache.delete(entry.channel)
      this.cacheStats.evictedCount++
      logger.warn(`[DataFlowEngine] Cache evicted (LRU): channel="${entry.channel}", lastAccess=${entry.lastAccessAt}`)
    }
    this.cacheStats.totalEntries = this.cache.size
  }

  setCacheMaxEntries(max: number): void {
    this.cacheMaxEntries = max
    this.cacheStats.maxEntries = max
    logger.info(`[DataFlowEngine] Cache max entries set to ${max}`)
    this._evictIfNeeded()
  }

  registerRefresh<T>(channel: string, fetcher: () => Promise<T>, intervalMs?: number): void {
    logger.debug(`[DataFlowEngine] registerRefresh() called for "${channel}"`)

    const prevTimer = this.refreshTimers.has(channel)
    this.stopRefresh(channel)

    const meta = this.channelMeta.get(channel)
    const interval = intervalMs ?? meta?.refreshInterval ?? 30000

    if (!meta) {
      logger.warn(`[DataFlowEngine] registerRefresh for unknown channel "${channel}", using default interval=${interval}ms`)
    }

    const run = () => {
      const fetchStart = Date.now()
      logger.debug(`[DataFlowEngine] Refresh triggered for "${channel}"`)
      fetcher()
        .then((data) => {
          const fetchDuration = Date.now() - fetchStart
          logger.debug(`[DataFlowEngine] Refresh fetched "${channel}" in ${fetchDuration}ms`)
          this.publish(channel, data)
        })
        .catch((err) => {
          logger.warn(`[DataFlowEngine] Refresh failed for "${channel}"`, { error: err })
        })
    }

    run()
    const timer = setInterval(run, interval)
    this.refreshTimers.set(channel, timer)
    logger.info(`[DataFlowEngine] Refresh registered: channel="${channel}", interval=${interval}ms, wasUpdated=${prevTimer}`)
  }

  stopRefresh(channel: string): void {
    const timer = this.refreshTimers.get(channel)
    if (timer) {
      clearInterval(timer)
      this.refreshTimers.delete(channel)
      logger.info(`[DataFlowEngine] Refresh stopped: channel="${channel}"`)
    } else {
      logger.debug(`[DataFlowEngine] stopRefresh() called but no timer found for "${channel}"`)
    }
  }

  private _distribute<T>(packet: DataPacket<T>): void {
    const callbacks = this.subscribers.get(packet.channel)
    if (!callbacks || callbacks.size === 0) {
      logger.debug(`[DataFlowEngine] _distribute() skipped: no subscribers for "${packet.channel}"`)
      return
    }

    const startTs = Date.now()
    const meta = this.channelMeta.get(packet.channel)
    const channelPriority = meta?.priority ?? 'normal'
    const priorityValue = PRIORITY_ORDER[channelPriority] ?? 1
    const callbackArray = Array.from(callbacks)

    logger.debug(`[DataFlowEngine] _distribute(): channel="${packet.channel}", subscribers=${callbackArray.length}, priority=${channelPriority}`)

    callbackArray.forEach((cb, index) => {
      const exec = () => {
        const cbStart = Date.now()
        try {
          cb(packet)
          const cbDuration = Date.now() - cbStart
          if (cbDuration > 16) {
            logger.warn(`[DataFlowEngine] Slow subscriber: channel="${packet.channel}", #${index + 1}/${callbackArray.length}, duration=${cbDuration}ms`)
          } else if (cbDuration > 5) {
            logger.debug(`[DataFlowEngine] Subscriber #${index + 1} took ${cbDuration}ms for "${packet.channel}"`)
          }
        } catch (err) {
          logger.error(`[DataFlowEngine] Subscriber error: channel="${packet.channel}", #${index + 1}`, { error: err })
        }
      }

      if (priorityValue === 0) {
        exec()
      } else {
        queueMicrotask(exec)
      }
    })

    const dispatchDuration = Date.now() - startTs
    if (dispatchDuration > 5) {
      logger.info(`[DataFlowEngine] Dispatch completed: channel="${packet.channel}", subscribers=${callbackArray.length}, duration=${dispatchDuration}ms`)
    }
  }

  private _scheduleReconnect(url?: string): void {
    if (this.reconnectTimer) {
      logger.debug('[DataFlowEngine] Reconnect already scheduled')
      return
    }

    const delay = Math.min(1000 * 2 ** this.reconnectAttempts, this.maxReconnectDelay)
    this.reconnectAttempts++
    logger.info(`[DataFlowEngine] Scheduling SSE reconnect in ${delay}ms (attempt=${this.reconnectAttempts})`)

    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null
      this._tryReconnect(url)
    }, delay)
  }

  private _tryReconnect(url?: string): void {
    if (this.connected) {
      logger.debug('[DataFlowEngine] _tryReconnect() skipped - already connected')
      return
    }
    if (!url) {
      logger.debug('[DataFlowEngine] _tryReconnect() skipped - no URL')
      return
    }
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      logger.warn('[DataFlowEngine] Max reconnect attempts reached, falling back to polling')
      this._fallbackToPolling()
      return
    }
    logger.info(`[DataFlowEngine] Attempting SSE reconnect (attempt=${this.reconnectAttempts})`)
    this.connect(url)
  }

  private _fallbackToPolling(): void {
    logger.info('[DataFlowEngine] Falling back to polling mode')
    this.connected = true
    eventBus.emit(EVENT_NAMES.DATAFLOW_CONNECTED, { connected: true })
    this._notifyConnectionChange(true)
  }

  private _notifyConnectionChange(connected: boolean): void {
    logger.debug(`[DataFlowEngine] _notifyConnectionChange(): connected=${connected}, listeners=${this.connectionListeners.size}`)
    this.connectionListeners.forEach((l) => {
      try { l(connected) } catch (err) { logger.error('[DataFlowEngine] Connection listener error', { error: err }) }
    })
  }

  onConnectionChange(listener: (connected: boolean) => void): () => void {
    this.connectionListeners.add(listener)
    logger.debug(`[DataFlowEngine] Connection listener added, total=${this.connectionListeners.size}`)
    return () => {
      this.connectionListeners.delete(listener)
      logger.debug(`[DataFlowEngine] Connection listener removed, total=${this.connectionListeners.size}`)
    }
  }

  getStats() {
    const totalRequests = this.cacheStats.hitCount + this.cacheStats.missCount
    const hitRate = totalRequests > 0 ? (this.cacheStats.hitCount / totalRequests) * 100 : 0

    const stats = {
      connected: this.connected,
      channels: this.subscribers.size,
      subscribers: Array.from(this.subscribers.entries()).map(([ch, set]) => ({ channel: ch, count: set.size })),
      cacheEntries: this.cache.size,
      cacheMaxEntries: this.cacheMaxEntries,
      cacheHitRate: Number(hitRate.toFixed(2)),
      cacheExpiredCount: this.cacheStats.expiredCount,
      cacheEvictedCount: this.cacheStats.evictedCount,
      refreshTasks: this.refreshTimers.size,
    }
    logger.debug(`[DataFlowEngine] getStats(): ${JSON.stringify(stats)}`)
    return stats
  }

  getCacheStats(): CacheStats {
    return { ...this.cacheStats }
  }

  destroy(): void {
    logger.info('[DataFlowEngine] destroy() called')
    this.disconnect()
    this.subscribers.clear()
    this.cache.clear()
    this.connectionListeners.clear()
    logger.info('[DataFlowEngine] Destroyed: all resources cleaned up')
  }
}

export const dataFlowEngine = new DataFlowEngine()

/**
 * @module core/entityValidators
 * @lifecycle @Global
 * @description 核心实体充血模型 — 将校验逻辑从贫血 interface 中提取为独立验证函数
 *
 * 设计原则：
 * - 保持现有 interface 定义不变（渐进式增强，非破坏性重构）
 * - 校验函数以 `assertXxx` / `validateXxx` 命名，返回 `Result<T>` 类型
 * - 在 Store 写入入口（addOrder/saveScore）和 useCase 层调用
 *
 * @see AGENTS.md 第二章 "类型安全" 章节
 */

import type { Order, V6Score, Stock } from '@/data/types'

// ============================================================================
// 类型定义
// ============================================================================

export interface ValidationResult<T> {
  valid: boolean
  data?: T
  errors: string[]
}

export type OrderDirection = 'buy' | 'sell'

// ============================================================================
// Order 实体验证
// ============================================================================

/**
 * 验证订单实体的合法性
 *
 * 校验规则：
 * 1. symbol 非空且为有效字符串
 * 2. direction 必须为 'buy' 或 'sell'
 * 3. quantity 必须为正数且为有限数
 * 4. price 必须为正数且为有限数
 * 5. amount = quantity × price（自动计算，允许误差 0.01）
 */
export function validateOrder(order: Partial<Order>): ValidationResult<Order> {
  const errors: string[] = []

  // symbol 校验
  if (!order.symbol || typeof order.symbol !== 'string' || order.symbol.trim().length === 0) {
    errors.push('symbol 不能为空')
  } else if (order.symbol.length > 20) {
    errors.push('symbol 长度不能超过 20 个字符')
  }

  // direction 校验
  if (!order.direction) {
    errors.push('direction 不能为空')
  } else if (order.direction !== 'buy' && order.direction !== 'sell') {
    errors.push(`direction 必须为 'buy' 或 'sell'，当前: ${String(order.direction)}`)
  }

  // quantity 校验
  if (order.quantity === undefined || order.quantity === null) {
    errors.push('quantity 不能为空')
  } else if (typeof order.quantity !== 'number' || !Number.isFinite(order.quantity)) {
    errors.push('quantity 必须为有限数字')
  } else if (order.quantity <= 0) {
    errors.push('quantity 必须为正数')
  } else if (order.quantity > 1_000_000) {
    errors.push('quantity 不能超过 100 万')
  }

  // price 校验
  if (order.price === undefined || order.price === null) {
    errors.push('price 不能为空')
  } else if (typeof order.price !== 'number' || !Number.isFinite(order.price)) {
    errors.push('price 必须为有限数字')
  } else if (order.price <= 0) {
    errors.push('price 必须为正数')
  } else if (order.price > 1_000_000) {
    errors.push('price 不能超过 1,000,000')
  }

  // amount 校验（如果提供了 amount）
  if (order.amount !== undefined && order.quantity !== undefined && order.price !== undefined) {
    const expectedAmount = order.quantity * order.price
    if (Math.abs(order.amount - expectedAmount) > 0.01) {
      errors.push(`amount 不匹配: 预期 ${expectedAmount.toFixed(2)}，实际 ${order.amount}`)
    }
  }

  if (errors.length > 0) {
    return { valid: false, errors }
  }

  const amount = order.quantity! * order.price!
  return {
    valid: true,
    data: {
      ...order,
      amount: Math.round(amount * 100) / 100,
    } as Order,
    errors: [],
  }
}

/**
 * 断言订单合法，不合法时抛出 Error
 */
export function assertOrderValid(order: Partial<Order>): Order {
  const result = validateOrder(order)
  if (!result.valid || !result.data) {
    throw new Error(`订单校验失败: ${result.errors.join('; ')}`)
  }
  return result.data
}

// ============================================================================
// V6Score 实体验证
// ============================================================================

/**
 * 验证 V6 评分实体的合法性
 *
 * 校验规则：
 * 1. symbol 非空
 * 2. score 在 [0, 5] 范围内
 * 3. factors 不能为空对象
 * 4. algorithmVersion 非空
 * 5. calculatedAt 为有效时间戳
 */
export function validateV6Score(score: Partial<V6Score>): ValidationResult<V6Score> {
  const errors: string[] = []

  if (!score.symbol || score.symbol.trim().length === 0) {
    errors.push('symbol 不能为空')
  }

  if (score.score === undefined || score.score === null) {
    errors.push('score 不能为空')
  } else if (typeof score.score !== 'number' || !Number.isFinite(score.score)) {
    errors.push('score 必须为有限数字')
  } else if (score.score < 0 || score.score > 5) {
    errors.push(`score 必须在 [0, 5] 范围内，当前: ${score.score}`)
  }

  if (!score.factors || typeof score.factors !== 'object' || Object.keys(score.factors).length === 0) {
    errors.push('factors 不能为空')
  }

  if (!score.algorithmVersion || score.algorithmVersion.trim().length === 0) {
    errors.push('algorithmVersion 不能为空')
  }

  if (score.calculatedAt !== undefined && (typeof score.calculatedAt !== 'number' || score.calculatedAt <= 0)) {
    errors.push('calculatedAt 必须为正数时间戳')
  }

  if (errors.length > 0) {
    return { valid: false, errors }
  }

  return {
    valid: true,
    data: score as V6Score,
    errors: [],
  }
}

/**
 * 断言评分合法，不合法时抛出 Error
 */
export function assertV6ScoreValid(score: Partial<V6Score>): V6Score {
  const result = validateV6Score(score)
  if (!result.valid || !result.data) {
    throw new Error(`评分校验失败: ${result.errors.join('; ')}`)
  }
  return result.data
}

// ============================================================================
// Stock 实体验证
// ============================================================================

/**
 * 验证 Stock 实体的合法性
 *
 * 校验规则：
 * 1. symbol 非空
 * 2. name 非空
 * 3. researchStatus 为有效枚举值
 * 4. price（若提供）为正数
 * 5. pe/pb/roe（若提供）为有限数
 */
export function validateStock(stock: Partial<Stock>): ValidationResult<Stock> {
  const errors: string[] = []

  if (!stock.symbol || stock.symbol.trim().length === 0) {
    errors.push('symbol 不能为空')
  }

  if (!stock.name || stock.name.trim().length === 0) {
    errors.push('name 不能为空')
  }

  if (!stock.researchStatus) {
    errors.push('researchStatus 不能为空')
  }

  if (stock.price !== undefined && stock.price !== null) {
    if (typeof stock.price !== 'number' || !Number.isFinite(stock.price)) {
      errors.push('price 必须为有限数字')
    } else if (stock.price < 0) {
      errors.push('price 不能为负数')
    }
  }

  if (stock.pe !== undefined && stock.pe !== null) {
    if (typeof stock.pe !== 'number' || !Number.isFinite(stock.pe)) {
      errors.push('pe 必须为有限数字')
    }
  }

  if (stock.pb !== undefined && stock.pb !== null) {
    if (typeof stock.pb !== 'number' || !Number.isFinite(stock.pb)) {
      errors.push('pb 必须为有限数字')
    }
  }

  if (stock.roe !== undefined && stock.roe !== null) {
    if (typeof stock.roe !== 'number' || !Number.isFinite(stock.roe)) {
      errors.push('roe 必须为有限数字')
    }
  }

  if (errors.length > 0) {
    return { valid: false, errors }
  }

  return {
    valid: true,
    data: stock as Stock,
    errors: [],
  }
}

// ============================================================================
// 金额精度工具
// ============================================================================

/**
 * 将金额四舍五入到2位小数（分精度）
 */
export function roundAmount(amount: number): number {
  return Math.round(amount * 100) / 100
}

/**
 * 计算订单总金额 = quantity × price，保留2位小数
 */
export function computeOrderAmount(quantity: number, price: number): number {
  return roundAmount(quantity * price)
}

import { getLogger } from '@/lib/logger'
import type { EnvelopeAction, EnvelopeMeta, EnvelopeTarget, ModuleId } from '@/config/dbConfig'
import { ENVELOPE_TARGET } from '@/config/dbConfig'

const logger = getLogger()

export interface StandardEnvelope {
  meta: EnvelopeMeta
  payload: unknown
}

export class EnvelopeError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'EnvelopeError'
  }
}

interface ValidationResult {
  valid: boolean
  error?: string
}

export class EnvelopeFactory {
  static create(
    meta: Omit<EnvelopeMeta, 'timestamp'> & { timestamp?: number },
    payload: unknown,
  ): StandardEnvelope {
    logger.debug(`[EnvelopeFactory] create() called: action="${meta.action}", source="${meta.source}", target="${meta.target}"`)

    const envelope: StandardEnvelope = {
      meta: {
        ...meta,
        timestamp: meta.timestamp ?? Date.now(),
      },
      payload,
    }

    logger.info(`[EnvelopeFactory] Envelope created: action="${meta.action}", source="${meta.source}", traceId="${meta.traceId}"`)
    return envelope
  }

  static validate(envelope: StandardEnvelope): ValidationResult {
    logger.debug(`[EnvelopeFactory] validate() called`)

    if (!envelope || typeof envelope !== 'object') {
      logger.warn(`[EnvelopeFactory] Validation failed: Envelope must be an object`)
      return { valid: false, error: 'Envelope must be an object' }
    }

    const { meta, payload } = envelope

    if (!meta || typeof meta !== 'object') {
      logger.warn(`[EnvelopeFactory] Validation failed: Envelope meta is required`)
      return { valid: false, error: 'Envelope meta is required' }
    }

    if (!meta.source || typeof meta.source !== 'string') {
      logger.warn(`[EnvelopeFactory] Validation failed: Envelope source is required`)
      return { valid: false, error: 'Envelope source is required' }
    }

    if (!Object.values(ENVELOPE_TARGET).includes(meta.target as EnvelopeTarget)) {
      logger.warn(`[EnvelopeFactory] Validation failed: Invalid envelope target "${meta.target}"`)
      return { valid: false, error: `Invalid envelope target: ${meta.target}` }
    }

    if (!meta.action || typeof meta.action !== 'string') {
      logger.warn(`[EnvelopeFactory] Validation failed: Envelope action is required`)
      return { valid: false, error: 'Envelope action is required' }
    }

    if (!meta.traceId || typeof meta.traceId !== 'string') {
      logger.warn(`[EnvelopeFactory] Validation failed: Envelope traceId is required`)
      return { valid: false, error: 'Envelope traceId is required' }
    }

    if (typeof meta.timestamp !== 'number' || meta.timestamp <= 0) {
      logger.warn(`[EnvelopeFactory] Validation failed: Envelope timestamp must be a positive number`)
      return { valid: false, error: 'Envelope timestamp must be a positive number' }
    }

    if (payload === undefined) {
      logger.warn(`[EnvelopeFactory] Validation failed: Envelope payload is required`)
      return { valid: false, error: 'Envelope payload is required (can be null)' }
    }

    logger.debug(`[EnvelopeFactory] Validation passed: action="${meta.action}", traceId="${meta.traceId}"`)
    return { valid: true }
  }
}

export type { ModuleId, EnvelopeTarget, EnvelopeAction, EnvelopeMeta }

/**
 * @module MemoryCache
 * @description 独立内存缓存模块，支持 TTL（默认 10s）、LRU 淘汰（默认 200 条）、
 *              容量上限与自动过期清理。
 *
 * 使用场景：
 * - 高频访问的行情快照缓存
 * - 策略计算结果临时缓存
 * - API 响应去重缓存
 * - 跨组件共享的临时状态
 */

import { getLogger } from '@/lib/logger'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

/** 缓存条目元数据 */
interface CacheEntry<T> {
  value: T
  /** 创建时间戳 (ms) */
  createdAt: number
  /** TTL 毫秒数，0 表示永不过期 */
  ttl: number
  /** 最后访问时间戳 (ms)，用于 LRU 淘汰 */
  lastAccessedAt: number
  /** 访问次数（可选统计） */
  accessCount: number
}

/** MemoryCache 配置选项 */
export interface MemoryCacheOptions {
  /** TTL 毫秒数，默认 10000 (10s)，设为 0 表示永不过期 */
  defaultTTL?: number
  /** 最大条目数，默认 200，超出时按 LRU 淘汰 */
  maxSize?: number
  /** 清理间隔毫秒数，默认 30000 (30s)，设为 0 禁用自动清理 */
  cleanupInterval?: number
  /** 缓存命名空间，用于日志区分 */
  namespace?: string
}

/** 缓存统计信息 */
export interface CacheStats {
  size: number
  maxSize: number
  hitCount: number
  missCount: number
  evictionCount: number
  expiredCount: number
  /** 命中率 */
  hitRate: number
}

// ============================================================
// MemoryCache 实现
// ============================================================

export class MemoryCache<T = unknown> {
  private store = new Map<string, CacheEntry<T>>()
  private options: Required<MemoryCacheOptions>
  private stats: Omit<CacheStats, 'hitRate' | 'size'>
  private cleanupTimer: ReturnType<typeof setInterval> | null = null

  constructor(options: MemoryCacheOptions = {}) {
    this.options = {
      defaultTTL: options.defaultTTL ?? 10_000,
      maxSize: options.maxSize ?? 200,
      cleanupInterval: options.cleanupInterval ?? 30_000,
      namespace: options.namespace ?? 'default',
    }

    this.stats = {
      maxSize: this.options.maxSize,
      hitCount: 0,
      missCount: 0,
      evictionCount: 0,
      expiredCount: 0,
    }

    if (this.options.cleanupInterval > 0) {
      this.startCleanup()
    }

    logger.debug(`[MemoryCache:${this.options.namespace}] 初始化完成，maxSize=${this.options.maxSize}, TTL=${this.options.defaultTTL}ms, cleanupInterval=${this.options.cleanupInterval}ms`)
  }

  // ============================================================
  // 公共 API
  // ============================================================

  /**
   * 获取缓存值。
   * 命中时自动刷新 LRU 访问时间并增加命中计数。
   * 过期条目自动删除并返回 undefined。
   */
  get(key: string): T | undefined {
    const entry = this.store.get(key)

    if (!entry) {
      this.stats.missCount++
      logger.debug(`[MemoryCache:${this.options.namespace}] MISS: key="${key}"`)
      return undefined
    }

    if (this.isExpired(entry)) {
      this.store.delete(key)
      this.stats.expiredCount++
      this.stats.missCount++
      logger.debug(`[MemoryCache:${this.options.namespace}] EXPIRED: key="${key}"`)
      return undefined
    }

    // 更新 LRU 访问时间（使用 performance.now 保证亚毫秒精度）
    entry.lastAccessedAt = performance.now()
    entry.accessCount++
    this.stats.hitCount++

    logger.debug(`[MemoryCache:${this.options.namespace}] HIT: key="${key}"`)
    return entry.value
  }

  /**
   * 设置缓存值。
   * 若超出容量上限，自动淘汰最久未访问的条目。
   */
  set(key: string, value: T, ttl?: number): void {
    const effectiveTTL = ttl ?? this.options.defaultTTL

    // 如果 key 已存在，更新值并刷新时间
    if (this.store.has(key)) {
      const existing = this.store.get(key)!
      existing.value = value
      existing.createdAt = Date.now()
      existing.lastAccessedAt = performance.now()
      existing.ttl = effectiveTTL
      logger.debug(`[MemoryCache:${this.options.namespace}] UPDATE: key="${key}", TTL=${effectiveTTL}ms`)
      return
    }

    // 容量检查：超出上限则淘汰最旧的条目
    if (this.store.size >= this.options.maxSize) {
      this.evictLRU()
    }

    const entry: CacheEntry<T> = {
      value,
      createdAt: Date.now(),
      ttl: effectiveTTL,
      lastAccessedAt: performance.now(),
      accessCount: 0,
    }

    this.store.set(key, entry)
    logger.debug(`[MemoryCache:${this.options.namespace}] SET: key="${key}", TTL=${effectiveTTL}ms, size=${this.store.size}`)
  }

  /**
   * 删除指定缓存条目。
   */
  delete(key: string): boolean {
    const result = this.store.delete(key)
    if (result) {
      logger.debug(`[MemoryCache:${this.options.namespace}] DELETE: key="${key}"`)
    }
    return result
  }

  /**
   * 检查缓存条目是否存在且未过期。
   */
  has(key: string): boolean {
    const entry = this.store.get(key)
    if (!entry) return false
    if (this.isExpired(entry)) {
      this.store.delete(key)
      this.stats.expiredCount++
      return false
    }
    return true
  }

  /**
   * 清空全部缓存。
   */
  clear(): void {
    const count = this.store.size
    this.store.clear()
    logger.info(`[MemoryCache:${this.options.namespace}] CLEAR: 已清除 ${count} 条缓存`)
  }

  /**
   * 获取缓存统计信息。
   */
  getStats(): CacheStats {
    const total = this.stats.hitCount + this.stats.missCount
    return {
      ...this.stats,
      size: this.store.size,
      hitRate: total > 0 ? this.stats.hitCount / total : 0,
    }
  }

  /**
   * 重置统计计数。
   */
  resetStats(): void {
    this.stats.hitCount = 0
    this.stats.missCount = 0
    this.stats.evictionCount = 0
    this.stats.expiredCount = 0
    logger.debug(`[MemoryCache:${this.options.namespace}] 统计已重置`)
  }

  /**
   * 手动触发过期条目清理。
   * @returns 清理的条目数
   */
  purgeExpired(): number {
    const now = Date.now()
    let count = 0

    for (const [key, entry] of this.store.entries()) {
      if (this.isExpired(entry, now)) {
        this.store.delete(key)
        count++
      }
    }

    this.stats.expiredCount += count
    if (count > 0) {
      logger.debug(`[MemoryCache:${this.options.namespace}] 清理了 ${count} 条过期缓存`)
    }
    return count
  }

  /**
   * 获取当前缓存条目数。
   */
  get size(): number {
    return this.store.size
  }

  /**
   * 销毁缓存实例，停止自动清理定时器。
   */
  destroy(): void {
    this.stopCleanup()
    this.store.clear()
    logger.info(`[MemoryCache:${this.options.namespace}] 已销毁`)
  }

  // ============================================================
  // 私有方法
  // ============================================================

  /**
   * 判断缓存条目是否已过期。
   */
  private isExpired(entry: CacheEntry<T>, now: number = Date.now()): boolean {
    if (entry.ttl <= 0) return false // 永不过期
    return now - entry.createdAt > entry.ttl
  }

  /**
   * LRU 淘汰：删除最久未访问的条目。
   */
  private evictLRU(): void {
    let oldestKey: string | null = null
    let oldestTime = Infinity

    for (const [key, entry] of this.store.entries()) {
      if (entry.lastAccessedAt < oldestTime) {
        oldestTime = entry.lastAccessedAt
        oldestKey = key
      }
    }

    if (oldestKey) {
      this.store.delete(oldestKey)
      this.stats.evictionCount++
      logger.debug(`[MemoryCache:${this.options.namespace}] LRU EVICT: key="${oldestKey}", lastAccess=${new Date(oldestTime).toISOString()}`)
    }
  }

  /**
   * 启动自动清理定时器。
   */
  private startCleanup(): void {
    this.cleanupTimer = setInterval(() => {
      const count = this.purgeExpired()
      if (count > 0) {
        logger.debug(`[MemoryCache:${this.options.namespace}] 自动清理完成，已清除 ${count} 条过期缓存`)
      }
    }, this.options.cleanupInterval)
  }

  /**
   * 停止自动清理定时器。
   */
  private stopCleanup(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer)
      this.cleanupTimer = null
    }
  }
}

// ============================================================
// 默认实例（单例）
// ============================================================

/** 默认全局内存缓存实例 */
export const defaultCache = new MemoryCache({ namespace: 'global' })

/**
 * 创建并返回一个命名空间隔离的 MemoryCache 实例。
 * 适合模块级使用，避免 key 冲突。
 */
export function createCache(namespace: string, options?: Omit<MemoryCacheOptions, 'namespace'>): MemoryCache {
  return new MemoryCache({ ...options, namespace })
}

import { getLogger } from '@/lib/logger'
import {
  RESEARCH_STATUS,
  type ResearchStatus,
} from '@/config/dbConfig'

const logger = getLogger()

export const POOL_TRANSITIONS: Record<
  ResearchStatus,
  { next: ResearchStatus[]; label: string }
> = {
  [RESEARCH_STATUS.candidate]: {
    next: [RESEARCH_STATUS.screened, RESEARCH_STATUS.archived],
    label: '意向候选池',
  },
  [RESEARCH_STATUS.screened]: {
    next: [RESEARCH_STATUS.deepDive, RESEARCH_STATUS.archived],
    label: '研究精选池',
  },
  [RESEARCH_STATUS.deepDive]: {
    next: [RESEARCH_STATUS.watching, RESEARCH_STATUS.archived],
    label: '深度研究池',
  },
  [RESEARCH_STATUS.watching]: {
    next: [RESEARCH_STATUS.archived],
    label: '观察池',
  },
  [RESEARCH_STATUS.archived]: {
    next: [RESEARCH_STATUS.candidate],
    label: '归档池',
  },
}

export function getNextStatuses(status: ResearchStatus): ResearchStatus[] {
  const nextStatuses = POOL_TRANSITIONS[status].next
  logger.debug(`[PoolTransition] getNextStatuses: current="${status}", next=${JSON.stringify(nextStatuses)}`)
  return nextStatuses
}

export function getPoolLabel(status: ResearchStatus): string {
  const label = POOL_TRANSITIONS[status].label
  logger.debug(`[PoolTransition] getPoolLabel: status="${status}", label="${label}"`)
  return label
}

export function isValidTransition(
  from: ResearchStatus,
  to: ResearchStatus,
): boolean {
  const isValid = POOL_TRANSITIONS[from].next.includes(to)
  if (isValid) {
    logger.info(`[PoolTransition] isValidTransition: valid, from="${from}" → to="${to}"`)
  } else {
    logger.warn(`[PoolTransition] isValidTransition: invalid, from="${from}" → to="${to}", allowed=${JSON.stringify(POOL_TRANSITIONS[from].next)}`)
  }
  return isValid
}

export function getTransitionLabel(
  from: ResearchStatus,
  to: ResearchStatus,
): string {
  const labels: Record<ResearchStatus, string> = {
    [RESEARCH_STATUS.candidate]: '退回候选',
    [RESEARCH_STATUS.screened]: '精选研究',
    [RESEARCH_STATUS.deepDive]: '深度研究',
    [RESEARCH_STATUS.watching]: '加入观察',
    [RESEARCH_STATUS.archived]: '归档',
  }
  const label = labels[to] ?? '流转'
  logger.debug(`[PoolTransition] getTransitionLabel: from="${from}" → to="${to}", label="${label}"`)
  return label
}

export function transitionStatus(
  from: ResearchStatus,
  to: ResearchStatus,
): ResearchStatus | null {
  logger.debug(`[PoolTransition] transitionStatus() called: from="${from}", to="${to}"`)

  if (!isValidTransition(from, to)) {
    logger.error(`[PoolTransition] transitionStatus() failed: Invalid transition from="${from}" to="${to}"`)
    return null
  }

  logger.info(`[PoolTransition] transitionStatus() success: from="${from}" → to="${to}"`)
  return to
}

export interface PoolTransitionOption {
  value: ResearchStatus
  label: string
}

/**
 * 获取某状态的流转选项（纯计算函数，无数据 CRUD）
 */
export function getPoolTransitionOptions(status: ResearchStatus): PoolTransitionOption[] {
  return getNextStatuses(status).map((value) => ({
    value,
    label: getTransitionLabel(status, value),
  }))
}

/**
 * @module core/routeGuard
 * @lifecycle @Global
 * @description 路由守卫 — 提供路由级鉴权拦截和按钮级权限检查
 *
 * 解决问题：
 * - App.tsx 无路由守卫，所有路由直接渲染
 * - ACL 仅模块级+CRUD级，无按钮级权限
 *
 * 使用方式：
 * 1. 在 App.tsx 中用 <GuardedRoute> 替换 <Route>
 * 2. 在组件中调用 hasPermission('trading', 'button', 'export') 检查按钮级权限
 */

import React, { type ReactNode } from 'react'
import { Navigate, Route, useLocation } from 'react-router'
import { getLogger } from '@/lib/logger'
import { MODULE_ID } from '@/config/dbConfig'
import { ROUTE_WHITELIST } from '@/config/routes'

const logger = getLogger()

// ============================================================================
// 权限类型定义
// ============================================================================

export type PermissionLevel = 'route' | 'module' | 'button' | 'crud'
export type CrudAction = 'create' | 'read' | 'update' | 'delete'

export interface PermissionContext {
  module: string
  level: PermissionLevel
  action?: string
  storeName?: string
}

export type PermissionChecker = (ctx: PermissionContext) => boolean

// ============================================================================
// 按钮级权限注册表
// ============================================================================

/** 按钮级权限规则：module → action[]（白名单模式） */
const buttonPermissionRegistry: Record<string, Set<string>> = {}

/**
 * 注册按钮级权限规则
 */
export function registerButtonPermission(module: string, actions: string[]): void {
  buttonPermissionRegistry[module] = new Set(actions)
  logger.debug(`[routeGuard] 注册按钮权限: module=${module}, actions=${actions.join(',')}`)
}

/**
 * 路由级白名单 — 与 routes.ts 的 RouteCategory 保持一致
 * 不使用 MODULE_ID（数据库模块ID），因为路由类别与数据库模块是不同概念
 */
const ALLOWED_ROUTE_CATEGORIES: ReadonlyArray<string> = [
  'portal',
  'input',
  'analysis',
  'trading',
  'output',
  'command',
  'system',
  'other',
]

/**
 * 检查是否拥有指定权限
 */
export const hasPermission: PermissionChecker = (ctx): boolean => {
  // Route 级：检查模块是否在路由白名单中，同时验证路径合法性
  if (ctx.level === 'route') {
    if (!ALLOWED_ROUTE_CATEGORIES.includes(ctx.module)) return false
    // 若提供了 storeName（此处复用为路径前缀），检查是否在 ROUTE_WHITELIST 中
    if (ctx.storeName && ROUTE_WHITELIST.size > 0 && !ROUTE_WHITELIST.has(ctx.storeName)) {
      return false
    }
    return true
  }

  // Module 级：检查模块是否已注册
  if (ctx.level === 'module') {
    return Object.keys(buttonPermissionRegistry).includes(ctx.module)
  }

  // Button 级：检查 action 是否在模块白名单中
  if (ctx.level === 'button' && ctx.action) {
    const actions = buttonPermissionRegistry[ctx.module]
    if (!actions) return true // 未注册的模块默认允许（渐进式启用）
    return actions.has(ctx.action)
  }

  // CRUD 级：委托给 ACL_MATRIX（已在 acl.ts 中实现）
  if (ctx.level === 'crud') {
    return true // ACL_MATRIX 已处理
  }

  return true
}

/**
 * React Hook：在组件中检查按钮级权限
 *
 * @example
 * const canExport = usePermission('trading', 'button', 'export')
 * if (!canExport) return <Button disabled>导出（无权限）</Button>
 */
export function usePermission(
  module: string,
  level: PermissionLevel = 'button',
  action?: string,
): boolean {
  return hasPermission({ module, level, action })
}

// ============================================================================
// 路由守卫组件
// ============================================================================

export interface RouteGuardProps {
  children: ReactNode
  /** 模块ID，用于路由级鉴权 */
  module?: string
  /** 未授权时重定向到哪个路径 */
  redirectTo?: string
}

/**
 * 路由守卫组件 — 包裹在 Route element 中使用
 *
 * @example
 * <Route path="/trading" element={
 *   <RouteGuard module="trading">
 *     <TradingApp />
 *   </RouteGuard>
 * } />
 */
export function RouteGuard({
  children,
  module,
  redirectTo = '/',
}: RouteGuardProps): React.JSX.Element | null {
  const location = useLocation()

  // 如果指定了模块，检查路由级权限
  if (module && !hasPermission({ module, level: 'route' })) {
    logger.warn(`[RouteGuard] 访问被拒绝: path="${location.pathname}", module="${module}"`)
    return <Navigate to={redirectTo} replace state={{ from: location }} />
  }

  return <>{children}</>
}

/**
 * 受保护的路由组件 — 替代原有的 <Route> 直接渲染
 *
 * @example
 * <GuardedRoute path="/trading" module="trading" component={TradingApp} />
 */
export interface GuardedRouteProps {
  path: string
  component: React.ComponentType
  module?: string
  redirectTo?: string
}

export function GuardedRoute({
  path,
  component: Component,
  module,
  redirectTo,
}: GuardedRouteProps): React.JSX.Element {
  return (
    <Route
      path={path}
      element={
        <RouteGuard module={module} redirectTo={redirectTo}>
          <Component />
        </RouteGuard>
      }
    />
  )
}

